<?php
/**
 * Global page preloader for REGIONAL (custom file - not generated by PHPMaker).
 * Included from _shared/foot.php, so it survives regeneration and applies to
 * every page with header/footer. Uses only existing Bootstrap classes.
 *
 * The overlay stays up until the page has finished loading AND the data
 * requests the page fires on start-up (fetch / XHR) have come back, so users
 * see the page with its records already filled in instead of empty tables.
 *
 * This file is included at the very end of the document, so a page's own
 * inline <script> must defer its initial fetch()/XHR calls until after
 * DOMContentLoaded - otherwise they'd fire before this patch is installed
 * and go untracked (see e.g. the bootstrap block at the end of
 * pages/BudgetVarianceTable.php for the pattern to follow).
 */

// Animated NHA logo (SVGator). It animates with its own embedded <script>, so it
// must be inlined as markup - an <img src="...svg"> would never run that script
// and would show a still logo. Same approach as the login page (index.php).
$preloaderLogo = @file_get_contents(dirname(__DIR__, 1) . '/_shared/images/nha-logo-amin.svg') ?: '';
if ($preloaderLogo !== '') {
    $preloaderLogo = str_replace(
        '<svg id="eNuldLC5tMO1"',
        '<svg id="eNuldLC5tMO1" width="72" height="72" style="display:block;flex-shrink:0;" aria-hidden="true"',
        $preloaderLogo
    );
}
?>
<!-- Full-screen overlay with the card centered (inline styles so theme styles can't override it).
     Shown/hidden by toggling the .pp-hidden class (see <style> below) rather than display:none,
     so the fade is a smooth opacity/scale transition instead of an abrupt cut. -->
<style>
    #page-preloader {
        opacity: 1;
        visibility: visible;
        transition: opacity .25s ease, visibility 0s linear 0s;
    }
    #page-preloader .card {
        transform: scale(1);
        transition: transform .25s ease;
    }
    #page-preloader.pp-hidden {
        opacity: 0;
        visibility: hidden;
        /* delay the visibility flip until the fade-out finishes, so the overlay still
           blocks clicks/renders while fading instead of vanishing mid-transition */
        transition: opacity .25s ease, visibility 0s linear .25s;
    }
    #page-preloader.pp-hidden .card {
        transform: scale(.96);
    }
</style>
<div id="page-preloader" role="status" aria-live="polite"
     style="position:fixed;inset:0;z-index:999999;display:flex;align-items:center;justify-content:center;
            background:rgba(15,32,69,.55);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);">
    <div class="card border-0 shadow-lg rounded-3 m-0">
        <div class="card-body d-flex align-items-center gap-3 px-4 py-3">
            <?php if ($preloaderLogo !== ''): ?>
                <?= $preloaderLogo ?>
            <?php else: ?>
                <div class="spinner-border text-primary"></div>
            <?php endif; ?>
            <div>
                <div class="fw-semibold">Loading…</div>
                <div class="small text-muted">Please wait a moment</div>
            </div>
        </div>
    </div>
</div>
<script>
(function () {
    if (window.__preloaderLoaded) return;
    window.__preloaderLoaded = true;

    var SAFETY_TIMEOUT = 20000; // never block the screen longer than this (ms), even if a request hangs
    var QUIET_MS       = 400;   // requests must stay idle this long - catches follow-up calls a page chains on

    // Background calls that must not hold the loader (keep-alive pings, third-party
    // widget APIs that should stay non-blocking even if they're slow/unreachable, etc.)
    var IGNORE_URLS = [/\/session\?/, /ipapi\.co/, /open-meteo\.com/];

    var el = document.getElementById("page-preloader");
    if (!el) return;

    var safetyTimer    = null;
    var quietTimer     = null;
    var skipNextUnload = false;
    var pageLoaded     = document.readyState === "complete";
    var initialDone    = false; // true once the first load has finished - later requests no longer hold it
    var pending        = 0;

    function hide() {
        clearTimeout(safetyTimer);
        clearTimeout(quietTimer);
        initialDone = true;
        el.classList.add("pp-hidden");
    }

    function show() {
        el.classList.remove("pp-hidden");
        clearTimeout(safetyTimer);
        safetyTimer = setTimeout(hide, SAFETY_TIMEOUT);
    }

    // Hide once the page is loaded and no data request has been in flight for QUIET_MS.
    // The two animation frames let the browser paint the freshly loaded data first.
    function scheduleHide() {
        clearTimeout(quietTimer);
        if (initialDone || !pageLoaded || pending > 0) return;
        quietTimer = setTimeout(function () {
            if (pending > 0) return;
            requestAnimationFrame(function () { requestAnimationFrame(hide); });
        }, QUIET_MS);
    }

    function isIgnored(url) {
        url = String(url || "");
        return IGNORE_URLS.some(function (re) { return re.test(url); });
    }

    function begin() { pending++; clearTimeout(quietTimer); }
    function end()   { pending = Math.max(0, pending - 1); scheduleHide(); }

    // ── Track fetch() - most NHA pages load their records this way ──
    if (window.fetch) {
        var nativeFetch = window.fetch;
        window.fetch = function (input) {
            var url = typeof input === "string" ? input : (input && input.url);
            if (initialDone || isIgnored(url)) return nativeFetch.apply(this, arguments);
            begin();
            return nativeFetch.apply(this, arguments).finally(end);
        };
    }

    // ── Track XMLHttpRequest - jQuery / DataTables / PHPMaker ajax ──
    var nativeOpen = XMLHttpRequest.prototype.open;
    var nativeSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function (method, url) {
        this.__preloaderUrl = url;
        return nativeOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function () {
        if (!initialDone && !isIgnored(this.__preloaderUrl)) {
            begin();
            this.addEventListener("loadend", end, { once: true });
        }
        return nativeSend.apply(this, arguments);
    };

    // Links that download a file do not leave the page, so skip the loader for them
    function isDownloadLink(a) {
        if (a.hasAttribute("download")) return true;
        var href = a.getAttribute("href") || "";
        return /[?&]export=|\/export\/|download|\.(pdf|docx?|xlsx?|csv|zip)(\?|#|$)/i.test(href);
    }

    document.addEventListener("click", function (e) {
        var a = e.target.closest && e.target.closest("a[href]");
        if (a && isDownloadLink(a)) skipNextUnload = true;
    }, true);

    // Fires for every way of leaving the page: links, window.location redirects, form submits
    window.addEventListener("beforeunload", function () {
        if (skipNextUnload) {
            skipNextUnload = false;
            return;
        }
        show();
    });

    window.addEventListener("load", function () {
        pageLoaded = true;
        scheduleHide();
    });

    // Back/forward button restores the page from cache with the loader still visible
    window.addEventListener("pageshow", function (e) {
        if (e.persisted) hide();
    });

    safetyTimer = setTimeout(hide, SAFETY_TIMEOUT);
    scheduleHide();

    // Manual control if a page ever needs it: PagePreloader.show() / PagePreloader.hide()
    window.PagePreloader = { show: show, hide: hide };
})();
</script>
